def _turn_tokens(graph, turn: Node) -> int:
    """The containing turn's tokens = sum of input+output over the assistants it contains."""
    total = 0
    frontier = list(turn.children)
    while frontier:
        nid = frontier.pop(0)
        node = graph.nodes.get(nid)
        if node is None:
            continue
        if node.type is NodeType.ASSISTANT:
            total += (node.attrs.get("input_tokens") or 0) + (node.attrs.get("output_tokens") or 0)
        frontier.extend(node.children)
    return total


